"""Command line interface for libcrypto using only the Python standard library."""
from __future__ import annotations

import argparse
import sys
from typing import Iterable, List

from . import __version__
from .keys import PrivateKey
from .messages import (
    recover_address_bitcoin,
    recover_address_ethereum,
    sign_message_bitcoin,
    sign_message_ethereum,
    verify_message_bitcoin,
    verify_message_ethereum,
)
from .mnemonic import generate_mnemonic, validate_mnemonic
from .validation import get_address_info, validate_address
from .wallet import COIN_CONFIG, Wallet

_DEFAULT_COINS = [
    "bitcoin",
    "ethereum",
    "tron",
    "ripple",
    "litecoin",
    "dogecoin",
    "dash",
    "bitcoin_cash",
]


def _print_key_values(title: str, rows: Iterable[tuple[str, str]]) -> None:
    print(title)
    print("-" * 33)
    for key, value in rows:
        print(f"{key}: {value}")


def _command_info(_: argparse.Namespace) -> int:
    _print_key_values(
        "libcrypto",
        [
            ("Version", __version__),
            ("Description", "A professional library for cryptography and cryptocurrencies in Python."),
            ("Repository", "https://github.com/Pymmdrza/libcrypto"),
        ],
    )
    return 0


def _command_generate(args: argparse.Namespace) -> int:
    wallet = Wallet(args.private_key) if args.private_key else Wallet.generate()

    _print_key_values(
        "Wallet Keys",
        [
            ("Private Key (Hex)", wallet.private_key.hex),
            ("Private Key (WIF)", wallet.private_key.to_wif()),
            ("Public Key (Compressed)", wallet._public_key_compressed.hex),
            ("Public Key (Uncompressed)", wallet._public_key_uncompressed.hex),
        ],
    )

    print("\nGenerated Addresses")
    print("-" * 33)
    for coin in args.coins:
        coin = coin.lower()
        if coin not in COIN_CONFIG:
            print(f"{coin}: unsupported coin")
            continue
        for addr_type, address in wallet.get_all_addresses(coin).items():
            print(f"{coin} [{addr_type}]: {address}")
    return 0


def _command_mnemonic_generate(args: argparse.Namespace) -> int:
    print(generate_mnemonic(args.words))
    return 0


def _command_mnemonic_validate(args: argparse.Namespace) -> int:
    is_valid = validate_mnemonic(args.phrase)
    print("valid" if is_valid else "invalid")
    return 0 if is_valid else 1


def _command_validate_address(args: argparse.Namespace) -> int:
    is_valid = validate_address(args.address, args.network)
    info = get_address_info(args.address)
    _print_key_values(
        "Address Validation",
        [
            ("Address", args.address),
            ("Valid", "yes" if is_valid else "no"),
            ("Format", info.address_format or "unknown"),
            ("Type", info.address_type or "unknown"),
            ("Networks", ", ".join(info.networks) if info.networks else "unknown"),
        ],
    )
    return 0 if is_valid else 1


def _command_sign_message(args: argparse.Namespace) -> int:
    private_key = PrivateKey(args.private_key).int
    if args.coin == "ethereum":
        signature = sign_message_ethereum(private_key, args.message)
        print("0x" + signature.hex())
    else:
        print(sign_message_bitcoin(private_key, args.message))
    return 0


def _command_verify_message(args: argparse.Namespace) -> int:
    if args.coin == "ethereum":
        signature = bytes.fromhex(args.signature[2:] if args.signature.startswith("0x") else args.signature)
        is_valid = verify_message_ethereum(args.address, args.message, signature)
        recovered = recover_address_ethereum(args.message, signature) if is_valid else None
    else:
        is_valid = verify_message_bitcoin(args.address, args.message, args.signature)
        recovered = recover_address_bitcoin(args.message, args.signature) if is_valid else None

    print("valid" if is_valid else "invalid")
    if recovered:
        print(f"signer: {recovered}")
    return 0 if is_valid else 1


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="libcrypto",
        description="Manage crypto keys, addresses, and BIP39 mnemonics.",
    )
    parser.add_argument("--version", "-v", action="store_true", help="Show version and exit.")

    subparsers = parser.add_subparsers(dest="command")

    info_parser = subparsers.add_parser("info", help="Display package information.")
    info_parser.set_defaults(func=_command_info)

    generate_parser = subparsers.add_parser("generate", help="Generate wallet addresses.")
    generate_parser.add_argument(
        "--private-key",
        "-p",
        help="Generate addresses from an existing WIF or 64-character hex private key.",
    )
    generate_parser.add_argument(
        "--coin",
        "-c",
        dest="coins",
        action="append",
        default=None,
        help="Coin to generate. Can be used multiple times.",
    )
    generate_parser.set_defaults(func=_command_generate)

    mnemonic_parser = subparsers.add_parser("mnemonic", help="BIP39 mnemonic tools.")
    mnemonic_subparsers = mnemonic_parser.add_subparsers(dest="mnemonic_command")

    mnemonic_generate = mnemonic_subparsers.add_parser("generate", help="Generate a mnemonic phrase.")
    mnemonic_generate.add_argument("--words", "-w", type=int, default=12, help="Word count: 12, 15, 18, 21, or 24.")
    mnemonic_generate.set_defaults(func=_command_mnemonic_generate)

    mnemonic_validate = mnemonic_subparsers.add_parser("validate", help="Validate a mnemonic phrase.")
    mnemonic_validate.add_argument("phrase", help="Mnemonic phrase enclosed in quotes.")
    mnemonic_validate.set_defaults(func=_command_mnemonic_validate)

    validate_parser = subparsers.add_parser("validate", help="Validate a cryptocurrency address.")
    validate_parser.add_argument("address", help="Address to validate.")
    validate_parser.add_argument(
        "--network", "-n", default=None, help="Optional network the address must belong to."
    )
    validate_parser.set_defaults(func=_command_validate_address)

    sign_parser = subparsers.add_parser("sign-message", help="Sign a message.")
    sign_parser.add_argument("message", help="Message to sign, enclosed in quotes.")
    sign_parser.add_argument(
        "--coin", "-c", choices=["ethereum", "bitcoin"], default="ethereum", help="Signing scheme."
    )
    sign_parser.add_argument(
        "--private-key", "-p", required=True, help="Signing key as WIF or 64-character hex."
    )
    sign_parser.set_defaults(func=_command_sign_message)

    verify_parser = subparsers.add_parser("verify-message", help="Verify a signed message.")
    verify_parser.add_argument("message", help="Signed message, enclosed in quotes.")
    verify_parser.add_argument(
        "--coin", "-c", choices=["ethereum", "bitcoin"], default="ethereum", help="Signing scheme."
    )
    verify_parser.add_argument("--address", "-a", required=True, help="Expected signer address.")
    verify_parser.add_argument("--signature", "-s", required=True, help="Signature to verify.")
    verify_parser.set_defaults(func=_command_verify_message)

    return parser


def app(argv: List[str] | None = None) -> int:
    """Console-script entry point."""
    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.version:
        print(f"libcrypto version: {__version__}")
        return 0

    if not hasattr(args, "func"):
        parser.print_help()
        return 0

    if getattr(args, "coins", None) is None:
        args.coins = list(_DEFAULT_COINS)

    try:
        return int(args.func(args))
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1


# ``main`` is the canonical console-script entry point referenced by
# pyproject.toml ([project.scripts]). ``app`` is kept as a backward-compatible
# alias for callers that imported it directly.
main = app


if __name__ == "__main__":
    raise SystemExit(main())
